// internal/distributed/proxy/httpserver/utils.go lines 2192-2242
func generateSearchParams(reqSearchParams map[string]interface{}) ([]*commonpb.KeyValuePair, error) {
	var searchParams []*commonpb.KeyValuePair
	var params interface{}
	if val, ok := reqSearchParams[Params]; ok {
		params = val
	}

	paramsMap := make(map[string]interface{})
	if params != nil {
		var ok bool
		if paramsMap, ok = params.(map[string]interface{}); !ok {
			return nil, merr.WrapErrParameterInvalidMsg("searchParams.params must be a dict")
		}
	}

	// ... deepEqual function ...

	for key, value := range reqSearchParams {
		if val, ok := paramsMap[key]; ok {
			if !deepEqual(val, value) {
				return nil, merr.WrapErrParameterInvalidMsg(fmt.Sprintf("ambiguous parameter: %s...", key, value, val))
			}
		} else if key != Params {
			paramsMap[key] = value  // <-- NO RANGE VALIDATION: blindly accepts all keys including 'nprobe'
		}
	}

	bs, _ := json.Marshal(paramsMap)
	searchParams = append(searchParams, &commonpb.KeyValuePair{Key: Params, Value: string(bs)})

	for key, value := range reqSearchParams {
		if key != Params {
			// for compatibility
			if key == "ignoreGrowing" {
				key = common.IgnoreGrowing
			}
			searchParams = append(searchParams, &commonpb.KeyValuePair{Key: key, Value: fmt.Sprintf("%v", value)})  // <-- PASS-THROUGH: no validation
		}
	}

	return searchParams, nil
}

// KEY FINDING: The function does NOT check if 'nprobe' (or any search param) has valid range. It merely:
// 1. Merge searchParams into paramsMap
// 2. Serialize to JSON
// 3. Pass-through to downstream knowhere/index engine
// No range check like 'if key == "nprobe" && value < 1' exists anywhere in this function.
